import React, { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';
import { MainLayout } from '../../layout/MainLayout';
import {
  fetchCustomObjects,
  fetchCustomObjectFields,
  fetchCustomObjectRecords,
  type CustomObject,
  type CustomObjectField,
  type CustomObjectRecord,
} from '../../api/customObjects';
import { WorkspaceViewTabs } from '../../components/workspace/WorkspaceViewTabs';
import { useWorkspaceViewAccess } from '../../workspace/useWorkspaceViewAccess';
import { parseToLocalYMD, type LocalYMD } from '../../utils/calendarLocalDates';

const BAR_COLORS = [
  'linear-gradient(90deg,#93c5fd,#60a5fa)',
  'linear-gradient(90deg,#86efac,#4ade80)',
  'linear-gradient(90deg,#fcd34d,#fb923c)',
  'linear-gradient(90deg,#c4b5fd,#a78bfa)',
  'linear-gradient(90deg,#f9a8d4,#ec4899)',
];

function ymdToTime(p: LocalYMD): number {
  return new Date(p.y, p.m - 1, p.d).getTime();
}

function startOfWeekMonday(d: Date): Date {
  const x = new Date(d);
  const day = (x.getDay() + 6) % 7;
  x.setDate(x.getDate() - day);
  x.setHours(0, 0, 0, 0);
  return x;
}

export const WorkspaceGanttViewPage: React.FC = () => {
  const { t } = useTranslation();
  const { objectId = '' } = useParams();
  useWorkspaceViewAccess(objectId, 'gantt');
  const [fields, setFields] = useState<CustomObjectField[]>([]);
  const [objectMeta, setObjectMeta] = useState<CustomObject['meta'] | null>(null);
  const [records, setRecords] = useState<CustomObjectRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [anchor, setAnchor] = useState(() => startOfWeekMonday(new Date()));
  const [search, setSearch] = useState('');

  useEffect(() => {
    if (!objectId) return;
    setLoading(true);
    Promise.all([
      fetchCustomObjectFields(objectId),
      fetchCustomObjectRecords(objectId),
      fetchCustomObjects().catch(() => [] as CustomObject[]),
    ])
      .then(([loadedFields, res, objects]) => {
        setFields(loadedFields.filter((f) => f.isActive));
        setRecords(res.items);
        const object = objects.find((item) => item.id === objectId);
        setObjectMeta((object?.meta as Record<string, any> | null) || null);
      })
      .finally(() => setLoading(false));
  }, [objectId]);

  const cardTitleField = useMemo(() => {
    const saved = String((objectMeta as Record<string, any> | null)?.kanban?.cardTitleField || '').trim();
    if (saved) return saved;
    return (
      fields.find((f) => f.key === 'name')?.key ||
      fields.find((f) => f.key === 'title')?.key ||
      ''
    );
  }, [fields, objectMeta]);

  const dateKeys = useMemo(
    () => fields.filter((f) => f.type === 'date' || f.type === 'datetime').map((f) => f.key),
    [fields],
  );

  const resolveFieldText = (record: CustomObjectRecord, key: string) => {
    if (!key) return '';
    const raw = record.values?.[key];
    if (raw === undefined || raw === null) return '';
    return String(raw).trim();
  };

  const resolveTitle = (record: CustomObjectRecord) =>
    resolveFieldText(record, cardTitleField) ||
    String(record.values?.name || record.values?.title || record.id);

  const range = useMemo(() => {
    const start = new Date(anchor);
    const days = 21;
    const end = new Date(start);
    end.setDate(end.getDate() + days - 1);
    const dayMs = 86400000;
    const labels: Array<{ t: number; label: string }> = [];
    for (let i = 0; i < days; i++) {
      const d = new Date(start);
      d.setDate(d.getDate() + i);
      labels.push({
        t: d.getTime(),
        label: d.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short' }),
      });
    }
    return { startMs: start.getTime(), endMs: end.getTime() + dayMs - 1, labels, dayMs, days };
  }, [anchor]);

  const todayMs = useMemo(() => {
    const n = new Date();
    n.setHours(0, 0, 0, 0);
    return n.getTime();
  }, [anchor]);

  type RowBar = {
    record: CustomObjectRecord;
    title: string;
    leftPct: number;
    widthPct: number;
    bg: string;
  };

  const rows = useMemo(() => {
    const span = Math.max(1, range.endMs - range.startMs);
    const out: RowBar[] = [];
    const q = search.trim().toLowerCase();
    records.forEach((rec, idx) => {
      if (q && !resolveTitle(rec).toLowerCase().includes(q)) return;
      let startY = dateKeys[0] ? parseToLocalYMD(resolveFieldText(rec, dateKeys[0])) : null;
      let endY = dateKeys[1]
        ? parseToLocalYMD(resolveFieldText(rec, dateKeys[1]))
        : null;
      if (dateKeys.length === 1 && startY) {
        endY = startY;
      }
      if (!startY) {
        const c = parseToLocalYMD(rec.createdAt);
        if (!c) return;
        startY = c;
        endY = c;
      }
      if (!endY) endY = startY;
      let t0 = ymdToTime(startY);
      let t1 = ymdToTime(endY) + range.dayMs - 1;
      if (t1 < t0) [t0, t1] = [t1, t0];
      if (t1 < range.startMs || t0 > range.endMs) return;
      const clip0 = Math.max(t0, range.startMs);
      const clip1 = Math.min(t1, range.endMs);
      const leftPct = ((clip0 - range.startMs) / span) * 100;
      const widthPct = Math.max(0.8, ((clip1 - clip0) / span) * 100);
      out.push({
        record: rec,
        title: resolveTitle(rec),
        leftPct,
        widthPct,
        bg: BAR_COLORS[idx % BAR_COLORS.length],
      });
    });
    return out;
  }, [records, range, dateKeys, search, cardTitleField]);

  const todayLeftPct = useMemo(() => {
    if (todayMs < range.startMs || todayMs > range.endMs) return null;
    const span = Math.max(1, range.endMs - range.startMs);
    return ((todayMs - range.startMs) / span) * 100;
  }, [todayMs, range]);

  return (
    <MainLayout>
      <div className="max-w-[120rem] mx-auto space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className="text-2xl font-semibold text-slate-900">
              {t('crm.workspace.gantt.title')}
            </h1>
            <p className="text-sm text-slate-500">{t('crm.workspace.gantt.subtitle')}</p>
          </div>
          <WorkspaceViewTabs objectId={objectId} active="gantt" />
        </div>

        <div className="rounded-2xl border border-slate-200 bg-white shadow-sm overflow-hidden">
          <div className="flex flex-wrap items-center gap-2 border-b border-slate-100 px-4 py-3 bg-slate-50/80">
            <button
              type="button"
              className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-700 hover:bg-slate-50"
              onClick={() => {
                const d = new Date(anchor);
                d.setDate(d.getDate() - 14);
                setAnchor(startOfWeekMonday(d));
              }}
            >
              ←
            </button>
            <button
              type="button"
              className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-700 hover:bg-slate-50"
              onClick={() => setAnchor(startOfWeekMonday(new Date()))}
            >
              {t('crm.workspace.gantt.today')}
            </button>
            <button
              type="button"
              className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-700 hover:bg-slate-50"
              onClick={() => {
                const d = new Date(anchor);
                d.setDate(d.getDate() + 14);
                setAnchor(startOfWeekMonday(d));
              }}
            >
              →
            </button>
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={t('crm.workspace.gantt.search')}
              className="ml-auto w-full sm:w-64 rounded-xl border border-slate-200 px-3 py-2 text-sm"
            />
          </div>

          {loading ? (
            <div className="p-8 text-sm text-slate-500">{t('crm.workspace.common.loadingData')}</div>
          ) : dateKeys.length === 0 ? (
            <div className="p-8 text-sm text-amber-700 bg-amber-50/50">
              {t('crm.workspace.gantt.needDates')}
            </div>
          ) : (
            <div className="flex min-h-[320px]">
              <div className="w-52 shrink-0 border-r border-slate-100 bg-slate-50/40">
                <div className="h-10 border-b border-slate-100 px-3 flex items-center text-[11px] font-semibold uppercase tracking-wide text-slate-400">
                  {t('crm.workspace.gantt.tasks')}
                </div>
                {rows.map((r) => (
                  <div
                    key={r.record.id}
                    className="h-11 px-3 flex items-center text-sm text-slate-800 border-b border-slate-50 truncate"
                    title={r.title}
                  >
                    {r.title}
                  </div>
                ))}
                {rows.length === 0 && (
                  <div className="p-4 text-xs text-slate-500">{t('crm.workspace.gantt.empty')}</div>
                )}
              </div>
              <div className="flex-1 min-w-0 overflow-x-auto">
                <div className="min-w-[840px]">
                  <div
                    className="grid h-10 border-b border-slate-100 text-[10px] text-slate-500"
                    style={{ gridTemplateColumns: `repeat(${range.labels.length}, minmax(0,1fr))` }}
                  >
                    {range.labels.map((lab) => (
                      <div key={lab.t} className="border-l border-slate-100 px-1 flex items-end pb-1">
                        {lab.label}
                      </div>
                    ))}
                  </div>
                  <div className="relative">
                    {typeof todayLeftPct === 'number' && (
                      <div
                        className="pointer-events-none absolute top-0 bottom-0 z-10 w-px bg-sky-500/80"
                        style={{ left: `${todayLeftPct}%` }}
                      >
                        <span className="absolute -top-1 left-1 text-[9px] font-medium text-sky-600 whitespace-nowrap">
                          {t('crm.workspace.gantt.todayMarker')}
                        </span>
                      </div>
                    )}
                    {rows.map((r) => (
                      <div
                        key={r.record.id}
                        className="relative h-11 border-b border-slate-50 bg-white"
                      >
                        <div
                          className="absolute top-2 h-7 rounded-lg shadow-sm border border-white/40"
                          style={{
                            left: `${r.leftPct}%`,
                            width: `${r.widthPct}%`,
                            background: r.bg,
                            minWidth: 8,
                          }}
                          title={`${r.title}`}
                        />
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </MainLayout>
  );
};

const KEY = 'workspace_recent_tables_v1';

export function touchRecentWorkspaceTable(areaId: string, objectId: string, max = 24) {
  try {
    const raw = localStorage.getItem(KEY);
    const map = raw ? (JSON.parse(raw) as Record<string, string[]>) : {};
    const cur = Array.isArray(map[areaId]) ? map[areaId].filter((id) => id !== objectId) : [];
    const next = [objectId, ...cur].slice(0, max);
    map[areaId] = next;
    localStorage.setItem(KEY, JSON.stringify(map));
  } catch {
    /* ignore */
  }
}

export function readRecentWorkspaceTables(areaId: string): string[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const map = JSON.parse(raw) as Record<string, string[]>;
    const cur = map[areaId];
    return Array.isArray(cur) ? cur : [];
  } catch {
    return [];
  }
}

import React, { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  createWorkspaceArea,
  fetchWorkspaceAreas,
  type WorkspaceArea,
} from '../../api/workspaceAreas';
import { NAV_ICON_MAP, NavIconPlus, type NavIconKey } from '../layout/NavSidebarIcons';

const LS_KEY = 'lumiva_workspace_area_id';

type Props = {
  compact?: boolean;
  /** Текущая выбранная область (синхронизация с URL / parent) */
  activeAreaId: string | null;
};

function readStoredAreaId(): string | null {
  try {
    return localStorage.getItem(LS_KEY);
  } catch {
    return null;
  }
}

function writeStoredAreaId(id: string | null) {
  try {
    if (id) localStorage.setItem(LS_KEY, id);
    else localStorage.removeItem(LS_KEY);
  } catch {
    /* ignore */
  }
}

export const WorkspaceAreaSwitcher: React.FC<Props> = ({ compact = false, activeAreaId }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [areas, setAreas] = useState<WorkspaceArea[]>([]);
  const [loading, setLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const rootRef = useRef<HTMLDivElement | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const list = await fetchWorkspaceAreas();
      setAreas(list);
      const stored = readStoredAreaId();
      if (!activeAreaId && list.length && stored && list.some((a) => a.id === stored)) {
        navigate(`/workspace/areas/${stored}`, { replace: true });
      }
    } catch {
      setAreas([]);
    } finally {
      setLoading(false);
    }
  }, [activeAreaId, navigate]);

  useEffect(() => {
    void load();
  }, [load]);

  useLayoutEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDoc, true);
    return () => document.removeEventListener('mousedown', onDoc, true);
  }, [open]);

  const current = useMemo(() => {
    if (!activeAreaId) return areas[0] ?? null;
    return areas.find((a) => a.id === activeAreaId) ?? areas[0] ?? null;
  }, [areas, activeAreaId]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return areas;
    return areas.filter((a) => a.name.toLowerCase().includes(q));
  }, [areas, search]);

  const selectArea = (a: WorkspaceArea) => {
    writeStoredAreaId(a.id);
    setOpen(false);
    navigate(`/workspace/areas/${a.id}`);
  };

  const IconCmp =
    (current?.iconKey && NAV_ICON_MAP[current.iconKey as NavIconKey]) || NAV_ICON_MAP.folder;

  const handleCreate = async () => {
    if (!newName.trim() || creating) return;
    setCreating(true);
    try {
      const created = await createWorkspaceArea({
        name: newName.trim(),
        iconKey: 'folder',
        iconColor: '#6366f1',
      });
      setAreas((prev) => [...prev, created].sort((x, y) => x.sortOrder - y.sortOrder));
      setNewName('');
      selectArea(created);
    } finally {
      setCreating(false);
    }
  };

  if (loading && areas.length === 0) {
    return (
      <div
        className={`mb-2 rounded-xl border border-slate-200 bg-slate-50 px-2 py-2 text-[11px] text-slate-500 ${
          compact ? 'mx-0' : ''
        }`}
      >
        {t('crm.workspace.area.switcherLoading')}
      </div>
    );
  }

  return (
    <div ref={rootRef} className={`relative mb-2 ${compact ? '' : ''}`}>
      <div className="flex items-stretch gap-1">
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          className={`flex min-w-0 flex-1 items-center gap-2 rounded-xl border border-slate-200 bg-white px-2 py-2 text-left shadow-sm transition hover:border-slate-300 hover:bg-slate-50 ${
            compact ? 'justify-center px-1' : ''
          }`}
          title={current?.name}
        >
          <span
            className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-white shadow-inner"
            style={{ backgroundColor: current?.iconColor || '#3b82f6' }}
          >
            <IconCmp className="!h-4 !w-4 text-white" />
          </span>
          {!compact && (
            <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-slate-800">
              {current?.name || t('crm.workspace.area.noArea')}
            </span>
          )}
          {!compact && (
            <svg className="h-4 w-4 shrink-0 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          )}
        </button>
        <button
          type="button"
          onClick={() => {
            setOpen(false);
            navigate('/workspace/areas/new');
          }}
          className="inline-flex h-[42px] w-10 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-lumiva-accent text-white shadow-sm hover:opacity-95"
          title={t('crm.workspace.area.addArea')}
        >
          <NavIconPlus className="text-white" />
        </button>
      </div>

      {open && (
        <div
          className="absolute left-0 right-0 top-full z-[80] mt-1 overflow-hidden rounded-2xl border border-slate-200 bg-[#1e2139] text-slate-100 shadow-2xl"
          style={{ maxHeight: compact ? 'min(70vh, 380px)' : 'min(70vh, 420px)' }}
        >
          <div className="border-b border-white/10 p-2">
            <div className="relative">
              <svg
                className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={t('crm.workspace.area.searchAreas')}
                className="w-full rounded-xl border border-sky-500/40 bg-[#14162b] py-2 pl-9 pr-3 text-[13px] text-white placeholder:text-slate-500 outline-none focus:border-sky-400"
              />
            </div>
          </div>
          <div className="max-h-[220px] overflow-y-auto py-1">
            <div className="px-3 py-1 text-[10px] font-semibold uppercase tracking-wider text-slate-500">
              {t('crm.workspace.area.myAreas')}
            </div>
            {filtered.map((a) => {
              const I =
                (a.iconKey && NAV_ICON_MAP[a.iconKey as NavIconKey]) || NAV_ICON_MAP.folder;
              const active = current?.id === a.id;
              return (
                <button
                  key={a.id}
                  type="button"
                  onClick={() => selectArea(a)}
                  className={`flex w-full items-center gap-2 px-3 py-2 text-left text-[13px] transition ${
                    active ? 'bg-sky-600/25 text-white' : 'text-slate-200 hover:bg-white/5'
                  }`}
                >
                  <span
                    className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-white"
                    style={{ backgroundColor: a.iconColor || '#3b82f6' }}
                  >
                    <I className="!h-4 !w-4 text-white" />
                  </span>
                  <span className="min-w-0 flex-1 truncate">{a.name}</span>
                </button>
              );
            })}
            {filtered.length === 0 && (
              <div className="px-3 py-6 text-center text-xs text-slate-500">{t('crm.workspace.area.emptySearch')}</div>
            )}
          </div>
          <div className="border-t border-white/10 p-2 space-y-2">
            <div className="flex gap-2">
              <input
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
                placeholder={t('crm.workspace.area.newAreaPlaceholder')}
                className="min-w-0 flex-1 rounded-xl border border-white/10 bg-[#14162b] px-3 py-2 text-[13px] text-white placeholder:text-slate-500"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') void handleCreate();
                }}
              />
              <button
                type="button"
                disabled={creating || !newName.trim()}
                onClick={() => void handleCreate()}
                className="shrink-0 rounded-xl bg-sky-500 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50"
              >
                {creating ? '…' : '+'}
              </button>
            </div>
            <button
              type="button"
              onClick={() => {
                setOpen(false);
                navigate('/integrations-hub?tab=catalog');
              }}
              className="w-full rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-left text-[12px] text-slate-300 hover:bg-white/10"
            >
              {t('crm.workspace.area.browseIntegrations')}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

