import React, { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  fetchIntegrationHubCatalog,
  fetchIntegrations,
  type IntegrationConnectionDto,
  type IntegrationHubCatalogItem,
} from '../../api/integrations';
import {
  type WorkspaceIntegrationBinding,
  updateWorkspaceArea,
  type WorkspaceArea,
} from '../../api/workspaceAreas';
import { randomUUID } from '../../utils/randomUuid';

function newId() {
  try {
    return crypto.randomUUID();
  } catch {
    return randomUUID();
  }
}

type Props = {
  open: boolean;
  area: WorkspaceArea;
  onClose: () => void;
  onSaved: (next: WorkspaceArea) => void;
};

export const WorkspaceAreaIntegrationsModal: React.FC<Props> = ({
  open,
  area,
  onClose,
  onSaved,
}) => {
  const { t } = useTranslation();
  const [catalog, setCatalog] = useState<IntegrationHubCatalogItem[]>([]);
  const [connections, setConnections] = useState<IntegrationConnectionDto[]>([]);
  const [bindings, setBindings] = useState<WorkspaceIntegrationBinding[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [pickKey, setPickKey] = useState('');
  const [pickConn, setPickConn] = useState('');

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    Promise.all([fetchIntegrationHubCatalog(), fetchIntegrations()])
      .then(([cat, conn]) => {
        setCatalog(cat);
        setConnections(conn.filter((c) => !c.isDeleted && c.isEnabled));
      })
      .finally(() => setLoading(false));
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const raw = area.meta?.integrationBindings;
    if (!Array.isArray(raw)) {
      setBindings([]);
      return;
    }
    setBindings(
      raw.map((x: any) => ({
        id: String(x.id || newId()),
        catalogKey: String(x.catalogKey || ''),
        label: String(x.label || ''),
        connectionId: x.connectionId ?? null,
      })),
    );
  }, [open, area]);

  const catalogByKey = useMemo(() => {
    const m = new Map<string, IntegrationHubCatalogItem>();
    catalog.forEach((c) => m.set(c.key, c));
    return m;
  }, [catalog]);

  const workspaceFriendly = useMemo(
    () =>
      catalog.filter(
        (c) =>
          c.crmModules?.includes('workspace') ||
          c.crmModules?.includes('sales') ||
          c.crmModules?.includes('marketing'),
      ),
    [catalog],
  );

  const addBinding = () => {
    if (!pickKey) return;
    const item = catalogByKey.get(pickKey);
    const label = item?.name || pickKey;
    setBindings((prev) => [
      ...prev,
      {
        id: newId(),
        catalogKey: pickKey,
        label,
        connectionId: pickConn || null,
      },
    ]);
    setPickKey('');
    setPickConn('');
  };

  const removeBinding = (id: string) => {
    setBindings((prev) => prev.filter((b) => b.id !== id));
  };

  const save = async () => {
    setSaving(true);
    try {
      const nextMeta = {
        ...(area.meta && typeof area.meta === 'object' ? area.meta : {}),
        integrationBindings: bindings,
      };
      const updated = await updateWorkspaceArea(area.id, { meta: nextMeta });
      onSaved(updated);
      onClose();
    } finally {
      setSaving(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/40 p-4">
      <div className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl border border-slate-200 bg-white shadow-2xl">
        <div className="flex items-center justify-between border-b border-slate-100 px-4 py-3">
          <h2 className="text-lg font-semibold text-slate-900">
            {t('crm.workspace.area.integrations')}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1 text-slate-500 hover:bg-slate-100"
            aria-label="Close"
          >
            ✕
          </button>
        </div>
        <div className="space-y-4 p-4">
          <p className="text-sm text-slate-600">{t('crm.workspace.area.integrationsLead')}</p>
          {loading ? (
            <div className="text-sm text-slate-500">…</div>
          ) : (
            <>
              <div className="space-y-2">
                <div className="text-xs font-semibold uppercase tracking-wide text-slate-400">
                  {t('crm.workspace.area.bindingsTitle')}
                </div>
                {bindings.length === 0 && (
                  <div className="text-sm text-slate-500">{t('crm.workspace.area.bindingsEmpty')}</div>
                )}
                <ul className="space-y-2">
                  {bindings.map((b) => (
                    <li
                      key={b.id}
                      className="flex items-center justify-between gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm"
                    >
                      <span className="min-w-0 truncate font-medium text-slate-800">{b.label}</span>
                      <button
                        type="button"
                        className="shrink-0 text-rose-600 text-xs"
                        onClick={() => removeBinding(b.id)}
                      >
                        ×
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
              <div className="rounded-xl border border-dashed border-slate-200 p-3 space-y-2">
                <div className="text-xs font-medium text-slate-600">{t('crm.workspace.area.addBinding')}</div>
                <select
                  value={pickKey}
                  onChange={(e) => setPickKey(e.target.value)}
                  className="w-full rounded-lg border border-slate-300 px-2 py-2 text-sm"
                >
                  <option value="">{t('crm.workspace.area.catalogPick')}</option>
                  {workspaceFriendly.map((c) => (
                    <option key={c.key} value={c.key}>
                      {c.name}
                    </option>
                  ))}
                </select>
                <select
                  value={pickConn}
                  onChange={(e) => setPickConn(e.target.value)}
                  className="w-full rounded-lg border border-slate-300 px-2 py-2 text-sm"
                >
                  <option value="">{t('crm.workspace.area.connectionOptional')}</option>
                  {connections.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.name} ({c.kind})
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  onClick={addBinding}
                  disabled={!pickKey}
                  className="w-full rounded-lg bg-slate-900 py-2 text-sm font-medium text-white disabled:opacity-50"
                >
                  {t('crm.workspace.area.addBinding')}
                </button>
              </div>
            </>
          )}
          <div className="flex justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="rounded-xl border border-slate-200 px-4 py-2 text-sm"
            >
              {t('crm.common.cancel')}
            </button>
            <button
              type="button"
              disabled={saving}
              onClick={() => void save()}
              className="rounded-xl bg-lumiva-accent px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
            >
              {saving ? '…' : t('crm.workspace.area.saveBindings')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

