import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { MainLayout } from '../../layout/MainLayout';
import {
  fetchCustomObjects,
  updateCustomObject,
  type CustomObject,
} from '../../api/customObjects';
import { fetchWorkspaceArea, updateWorkspaceArea, type WorkspaceArea } from '../../api/workspaceAreas';
import { WorkspaceAreaIntegrationsModal } from '../../components/workspace/WorkspaceAreaIntegrationsModal';
import { NAV_ICON_MAP, type NavIconKey } from '../../components/layout/NavSidebarIcons';
import { parseEnabledViews } from '../../workspace/workspaceEnabledViews';
import { readRecentWorkspaceTables, touchRecentWorkspaceTable } from '../../workspace/workspaceRecentTables';
import { readWorkspaceIntegrationBindings } from '../../api/workspaceAreas';

type TabKey = 'recent' | 'content' | 'permissions';

const ICON_KEYS = Object.keys(NAV_ICON_MAP) as NavIconKey[];

export const WorkspaceAreaHomePage: React.FC = () => {
  const { t } = useTranslation();
  const { areaId = '' } = useParams();
  const navigate = useNavigate();
  const [area, setArea] = useState<WorkspaceArea | null>(null);
  const [objects, setObjects] = useState<CustomObject[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<TabKey>('recent');
  const [integrationsOpen, setIntegrationsOpen] = useState(false);
  const [coverDraft, setCoverDraft] = useState('');
  const [descDraft, setDescDraft] = useState('');
  const [savingProfile, setSavingProfile] = useState(false);
  const [iconPicker, setIconPicker] = useState(false);

  const load = useCallback(async () => {
    if (!areaId || !/^[0-9a-f-]{36}$/i.test(areaId)) return;
    setLoading(true);
    try {
      const [a, obs] = await Promise.all([
        fetchWorkspaceArea(areaId),
        fetchCustomObjects(areaId),
      ]);
      setArea(a);
      setObjects(obs);
      setCoverDraft(a.coverImageUrl || '');
      setDescDraft(a.description || '');
    } catch {
      setArea(null);
      setObjects([]);
    } finally {
      setLoading(false);
    }
  }, [areaId]);

  useEffect(() => {
    void load();
  }, [load]);

  const recentIds = useMemo(() => (areaId ? readRecentWorkspaceTables(areaId) : []), [areaId, objects]);
  const recentObjects = useMemo(() => {
    const map = new Map(objects.map((o) => [o.id, o]));
    return recentIds.map((id) => map.get(id)).filter(Boolean) as CustomObject[];
  }, [recentIds, objects]);

  const AreaIcon = (area?.iconKey && NAV_ICON_MAP[area.iconKey as NavIconKey]) || NAV_ICON_MAP.folder;

  const saveProfile = async () => {
    if (!area) return;
    setSavingProfile(true);
    try {
      const updated = await updateWorkspaceArea(area.id, {
        coverImageUrl: coverDraft.trim() || null,
        description: descDraft.trim() || null,
      });
      setArea(updated);
    } finally {
      setSavingProfile(false);
    }
  };

  const setAreaIcon = async (key: NavIconKey) => {
    if (!area) return;
    setIconPicker(false);
    const updated = await updateWorkspaceArea(area.id, { iconKey: key });
    setArea(updated);
  };

  const openTable = (o: CustomObject) => {
    if (areaId) touchRecentWorkspaceTable(areaId, o.id);
    navigate(`/workspace/${o.id}/table`);
  };

  const bindings = readWorkspaceIntegrationBindings(area?.meta);

  if (!areaId || !/^[0-9a-f-]{36}$/i.test(areaId)) {
    return (
      <MainLayout>
        <div className="p-8 text-slate-600">…</div>
      </MainLayout>
    );
  }

  if (!loading && !area) {
    return (
      <MainLayout>
        <div className="max-w-xl mx-auto p-8 text-center text-slate-600">
          {t('crm.workspace.tablesList.loadError')}
        </div>
      </MainLayout>
    );
  }

  return (
    <MainLayout>
      <div className="max-w-5xl mx-auto pb-16">
        <div className="overflow-hidden rounded-2xl border border-slate-200/90 bg-[#12152a] text-white shadow-xl">
          <div
            className="h-36 sm:h-44 w-full bg-cover bg-center relative"
            style={{
              backgroundImage: area?.coverImageUrl
                ? `url(${area.coverImageUrl})`
                : 'linear-gradient(135deg,#1e293b 0%,#312e81 50%,#0f172a 100%)',
            }}
          >
            <div className="absolute inset-0 bg-gradient-to-t from-[#12152a] via-transparent to-black/20" />
          </div>
          <div className="px-6 sm:px-8 pb-6 -mt-10 relative flex flex-wrap items-end gap-4">
            <div className="relative">
              <button
                type="button"
                onClick={() => setIconPicker((v) => !v)}
                className="flex h-16 w-16 sm:h-20 sm:w-20 items-center justify-center rounded-2xl text-2xl font-bold text-white shadow-lg ring-4 ring-[#12152a]"
                style={{ backgroundColor: area?.iconColor || '#3b82f6' }}
                title={t('crm.workspace.area.iconLabel')}
              >
                <AreaIcon className="!h-9 !w-9 text-white" />
              </button>
              {iconPicker && (
                <div className="absolute left-0 top-full z-30 mt-2 max-h-48 w-52 overflow-y-auto rounded-xl border border-slate-200 bg-white p-2 shadow-xl">
                  <div className="grid grid-cols-4 gap-1">
                    {ICON_KEYS.map((k) => {
                      const Ic = NAV_ICON_MAP[k];
                      return (
                        <button
                          key={k}
                          type="button"
                          className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-100 hover:bg-slate-50 text-slate-700"
                          onClick={() => void setAreaIcon(k)}
                        >
                          <Ic className="!h-4 !w-4" />
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
            <div className="min-w-0 flex-1 pb-1">
              <h1 className="text-2xl sm:text-3xl font-semibold tracking-tight">{area?.name}</h1>
              <p className="mt-1 text-sm text-slate-400 max-w-2xl">
                {t('crm.workspace.area.aiHint')}
              </p>
            </div>
            <div className="flex flex-wrap gap-2 pb-1">
              <button
                type="button"
                onClick={() => setIntegrationsOpen(true)}
                className="rounded-xl border border-white/20 bg-white/10 px-4 py-2 text-sm font-medium backdrop-blur hover:bg-white/15"
              >
                {t('crm.workspace.area.integrations')}
              </button>
              <button
                type="button"
                onClick={() => navigate(`/workspace/new?workspaceAreaId=${areaId}&finish=table`)}
                className="rounded-xl bg-sky-500 px-4 py-2 text-sm font-semibold text-white shadow hover:bg-sky-400"
              >
                {t('crm.workspace.area.newTable')}
              </button>
            </div>
          </div>

          <div className="px-6 sm:px-8 pb-6 space-y-4 border-t border-white/10 pt-4">
            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-[11px] font-medium uppercase tracking-wide text-slate-500 mb-1">
                  {t('crm.workspace.area.coverHint')}
                </label>
                <input
                  value={coverDraft}
                  onChange={(e) => setCoverDraft(e.target.value)}
                  className="w-full rounded-xl border border-white/10 bg-[#1a1f3a] px-3 py-2 text-sm text-white placeholder:text-slate-500"
                />
              </div>
              <div className="flex items-end">
                <button
                  type="button"
                  disabled={savingProfile}
                  onClick={() => void saveProfile()}
                  className="rounded-xl bg-white/10 px-4 py-2 text-sm font-medium hover:bg-white/15 disabled:opacity-50"
                >
                  {savingProfile ? '…' : t('crm.workspace.area.saveMeta')}
                </button>
              </div>
            </div>
            <textarea
              value={descDraft}
              onChange={(e) => setDescDraft(e.target.value)}
              onBlur={() => void saveProfile()}
              placeholder={t('crm.workspace.area.descriptionPlaceholder')}
              className="w-full min-h-[72px] rounded-xl border border-white/10 bg-[#1a1f3a] px-3 py-2 text-sm text-white placeholder:text-slate-500"
            />
          </div>
        </div>

        <div className="mt-8 flex flex-wrap gap-2 border-b border-slate-200 pb-0">
          {(
            [
              ['recent', t('crm.workspace.area.tabRecent')],
              ['content', t('crm.workspace.area.tabContent')],
              ['permissions', t('crm.workspace.area.tabPermissions')],
            ] as const
          ).map(([k, label]) => (
            <button
              key={k}
