import React, { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  createWorkspaceArea,
  fetchWorkspaceAreas,
  type WorkspaceArea,
} from '../../api/workspaceAreas';
import { NAV_ICON_MAP, NavIconPlus, type NavIconKey } from '../layout/NavSidebarIcons';

const LS_KEY = 'lumiva_workspace_area_id';

type Props = {
  compact?: boolean;
  /** Текущая выбранная область (синхронизация с URL / parent) */
  activeAreaId: string | null;
};

function readStoredAreaId(): string | null {
  try {
    return localStorage.getItem(LS_KEY);
  } catch {
    return null;
  }
}

function writeStoredAreaId(id: string | null) {
  try {
    if (id) localStorage.setItem(LS_KEY, id);
    else localStorage.removeItem(LS_KEY);
  } catch {
    /* ignore */
  }
}

const ROW_H = 'h-10';

export const WorkspaceAreaSwitcher: React.FC<Props> = ({ compact = false, activeAreaId }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [areas, setAreas] = useState<WorkspaceArea[]>([]);
  const [loading, setLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const rootRef = useRef<HTMLDivElement | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const list = await fetchWorkspaceAreas();
      setAreas(list);
      const stored = readStoredAreaId();
      if (!activeAreaId && list.length && stored && list.some((a) => a.id === stored)) {
        navigate(`/workspace/areas/${stored}`, { replace: true });
      }
    } catch {
      setAreas([]);
    } finally {
      setLoading(false);
    }
  }, [activeAreaId, navigate]);

  useEffect(() => {
    void load();
  }, [load]);

  useLayoutEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDoc, true);
    return () => document.removeEventListener('mousedown', onDoc, true);
  }, [open]);

  const current = useMemo(() => {
    if (!activeAreaId) return areas[0] ?? null;
    return areas.find((a) => a.id === activeAreaId) ?? areas[0] ?? null;
  }, [areas, activeAreaId]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return areas;
    return areas.filter((a) => a.name.toLowerCase().includes(q));
  }, [areas, search]);

  const selectArea = (a: WorkspaceArea) => {
    writeStoredAreaId(a.id);
    setOpen(false);
    navigate(`/workspace/areas/${a.id}`);
  };

  const IconCmp =
    (current?.iconKey && NAV_ICON_MAP[current.iconKey as NavIconKey]) || NAV_ICON_MAP.folder;

  const handleCreate = async () => {
    if (!newName.trim() || creating) return;
    setCreating(true);
    try {
      const created = await createWorkspaceArea({
        name: newName.trim(),
        iconKey: 'folder',
        iconColor: '#6366f1',
      });
      setAreas((prev) => [...prev, created].sort((x, y) => x.sortOrder - y.sortOrder));
      setNewName('');
      selectArea(created);
    } finally {
      setCreating(false);
    }
  };

  if (loading && areas.length === 0) {
    return (
      <div
        className={`mb-2 rounded-xl border border-slate-200 bg-slate-50 px-2 py-2 text-[11px] text-slate-500 ${
          compact ? 'mx-0' : ''
        }`}
      >
        {t('crm.workspace.area.switcherLoading')}
      </div>
    );
  }

  return (
    <div ref={rootRef} className={`relative mb-2 ${compact ? '' : ''}`}>
      <div className={`flex items-center gap-1.5 ${compact ? 'justify-center' : ''}`}>
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          className={`flex min-w-0 items-center gap-2 rounded-xl border border-slate-200 bg-white px-2.5 text-left shadow-sm transition hover:border-slate-300 hover:bg-slate-50/80 ${ROW_H} ${
            compact ? 'justify-center px-1.5' : 'flex-1'
          }`}
          title={current?.name}
        >
          <span
            className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-white shadow-sm"
            style={{ backgroundColor: current?.iconColor || '#3b82f6' }}
          >
            <IconCmp className="!h-4 !w-4 text-white" />
          </span>
          {!compact && (
            <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-[#222222]">
              {current?.name || t('crm.workspace.area.noArea')}
            </span>
          )}
          {!compact && (
            <svg className="h-4 w-4 shrink-0 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          )}
        </button>
        <button
          type="button"
          onClick={() => {
            setOpen(true);
            setSearch('');
            setTimeout(() => {
              try {
                rootRef.current?.querySelector('input[type="search"]')?.scrollIntoView({
                  block: 'nearest',
                });
              } catch {
                /* ignore */
              }
            }, 0);
          }}
          className={`inline-flex w-10 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-[#222222] text-white shadow-sm transition-colors hover:bg-black ${ROW_H}`}
          title={t('crm.workspace.area.addArea')}
        >
          <NavIconPlus className="!h-4 !w-4 !text-white" />
        </button>
      </div>

      {open && (
        <div
          className="absolute left-0 right-0 top-full z-[80] mt-1.5 overflow-hidden rounded-2xl border border-slate-200 bg-white text-slate-800 shadow-xl shadow-slate-900/10"
          style={{ maxHeight: compact ? 'min(70vh, 380px)' : 'min(70vh, 420px)' }}
        >
          <div className="border-b border-slate-100 p-2">
            <div className="relative">
              <svg
                className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
              <input
                type="search"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={t('crm.workspace.area.searchAreas')}
                className="w-full rounded-xl border border-slate-200 bg-white py-2 pl-9 pr-3 text-[13px] text-[#222222] placeholder:text-slate-400 outline-none focus:border-slate-400 focus:ring-1 focus:ring-slate-200"
              />
            </div>
          </div>
          <div className="max-h-[220px] overflow-y-auto py-1">
            <div className="px-3 py-1 text-[10px] font-semibold uppercase tracking-wider text-slate-400">
              {t('crm.workspace.area.myAreas')}
            </div>
            {filtered.map((a) => {
              const I =
                (a.iconKey && NAV_ICON_MAP[a.iconKey as NavIconKey]) || NAV_ICON_MAP.folder;
              const active = current?.id === a.id;
              return (
                <button
                  key={a.id}
                  type="button"
                  onClick={() => selectArea(a)}
                  className={`flex w-full items-center gap-2 px-3 py-2 text-left text-[13px] transition ${
                    active ? 'bg-slate-100 text-[#222222] font-medium' : 'text-slate-700 hover:bg-slate-50'
                  }`}
                >
                  <span
                    className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-white shadow-sm"
                    style={{ backgroundColor: a.iconColor || '#3b82f6' }}
                  >
                    <I className="!h-4 !w-4 text-white" />
                  </span>
                  <span className="min-w-0 flex-1 truncate">{a.name}</span>
                </button>
              );
            })}
            {filtered.length === 0 && (
              <div className="px-3 py-6 text-center text-xs text-slate-500">{t('crm.workspace.area.emptySearch')}</div>
            )}
          </div>
          <div className="border-t border-slate-100 p-2 space-y-2">
            <div className="flex items-center gap-2">
              <input
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
                placeholder={t('crm.workspace.area.newAreaPlaceholder')}
                className={`min-w-0 flex-1 rounded-xl border border-slate-200 bg-white px-3 text-[13px] text-[#222222] placeholder:text-slate-400 outline-none focus:border-slate-400 ${ROW_H}`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') void handleCreate();
                }}
              />
              <button
                type="button"
                disabled={creating || !newName.trim()}
                onClick={() => void handleCreate()}
                className={`inline-flex w-10 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-[#222222] text-sm font-semibold text-white transition hover:bg-black disabled:opacity-50 ${ROW_H}`}
              >
                {creating ? '…' : '+'}
              </button>
            </div>
            <button
              type="button"
              onClick={() => {
                setOpen(false);
                navigate('/integrations-hub?tab=catalog');
              }}
              className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-left text-[12px] text-slate-700 hover:bg-slate-100"
            >
              {t('crm.workspace.area.browseIntegrations')}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

