    setWooLoading(true);
    setWooAreaIssue(null);
    setWorkspaceAreaIdForLink(null);
    if (!objectId || !/^[0-9a-f-]{36}$/i.test(objectId)) {
      setWooConnections([]);
      setWooLoading(false);
      setWooAreaIssue('no_object_area');
      return;
