    try {
      const [obj, list] = await Promise.all([fetchCustomObject(objectId), fetchIntegrations()]);
      if (cancelled) return;
      const wid = obj.workspaceAreaId?.trim();
      if (!wid || !/^[0-9a-f-]{36}$/i.test(wid)) {
        setWooConnections([]);
        setWooAreaIssue('no_object_area');
        return;
      }
      setWorkspaceAreaIdForLink(wid);
      const area = await fetchWorkspaceArea(wid);
      if (cancelled) return;
      const bindings = readWorkspaceIntegrationBindings(area.meta);
      const allowed = new Set(
        bindings
          .map((b) => b.connectionId)
          .filter((id): id is string => typeof id === 'string' && /^[0-9a-f-]{36}$/i.test(id)),
      );
      if (allowed.size === 0) {
        setWooConnections([]);
        setWooAreaIssue('no_connection_bindings');
        return;
      }
      const woo = list.filter(
        (c) =>
          c.kind === 'woocommerce' &&
          !c.isDeleted &&
          c.isEnabled &&
          allowed.has(c.id),
      );
      setWooConnections(woo);
      if (woo.length === 0) {
        setWooAreaIssue('no_woo_among_bindings');
      }
    } catch {
      if (!cancelled) {
        setWooConnections([]);
        setWooAreaIssue('no_object_area');
      }
    } finally {
      if (!cancelled) setWooLoading(false);
    }
  })();
  return () => {
    cancelled = true;
  };
}, [objectId]);

