      const chunk = Array.isArray(body?.data) ? body.data : [];
      for (const row of chunk) {
        if (row && typeof row === 'object') {
          out.push(row as Record<string, unknown>);
        }
      }
      nextUrl = body?.paging?.next || null;
      if (!nextUrl) break;
    }
    return out;
  }
