const handleWooPreviewLoad = async () => {
  if (!objectId || !/^[0-9a-f-]{36}$/i.test(objectId) || !selectedWooIntegrationId) return;
  setWooPreviewLoading(true);
  setWooPreviewError(null);
  setMessage(null);
  try {
    const [res, freshFields] = await Promise.all([
      previewWooWorkspaceImport(selectedWooIntegrationId, objectId),
      fetchCustomObjectFields(objectId),
    ]);
    setFields(freshFields);
    setWooPreview(res);
    const nextImport: Record<string, boolean> = {};
    const nextMap: Record<string, string> = {};
    for (const col of res.columns) {
      nextImport[col] = true;
      nextMap[col] = suggestWooFieldForColumn(col, freshFields);
    }
    setWooColumnImport(nextImport);
    setWooColumnToField(nextMap);
    const st = freshFields.find((f) => f.type === 'status');
    setWooStatusFieldKey(st?.key || '');
  } catch (e: any) {
    setWooPreview(null);
    setWooPreviewError(e?.message || t('crm.workspace.import.wooPreviewError'));
  } finally {
    setWooPreviewLoading(false);
  }
};

const createWooFieldFromColumn = async (column: string) => {
  if (!wooPreview || !objectId) return;
  setWooCreatingColumn(column);
  setMessage(null);
  try {
    const key = toFieldKey(column);
    const rawType =
      column === 'status' || column.toLowerCase().includes('status')
        ? 'status'
        : inferType(column);
    const type = rawType === 'file' ? 'text' : rawType;
    const payload: Parameters<typeof createCustomObjectField>[1] = {
      key,
      label: column.trim() || key,
      type,
    };
    if (type === 'status' || type === 'select') {
      const uniques =
        wooPreview.uniqueValuesByColumn?.[column]?.filter((s) => s.trim()) ?? [];
      payload.options =
        uniques.length > 0
          ? statusOptionsFromFileValues(uniques)
          : type === 'status'
            ? DEFAULT_STATUS_FIELD_OPTIONS
            : [
                { value: 'low', label: 'Low' },
                { value: 'normal', label: 'Normal' },
                { value: 'high', label: 'High' },
              ];
    }
    const created = await createCustomObjectField(objectId, payload);
    setFields((prev) => [...prev, created]);
    setWooColumnToField((prev) => ({ ...prev, [column]: created.key }));
    if (created.type === 'status' && !wooStatusFieldKey) {
      setWooStatusFieldKey(created.key);
    }
    setMessage(t('crm.workspace.import.fieldCreated', { label: created.label, column }));
  } catch (e: any) {
    setMessage(e?.message || t('crm.workspace.import.createFieldError', { column }));
  } finally {
    setWooCreatingColumn(null);
  }
