          statusFieldKey: mapping.statusFieldKey ?? null,
        },
      );
      if (wr === 'created') workspaceCreated++;
      else if (wr === 'updated') workspaceUpdated++;
      else workspaceSkipped++;
    }
    if (batch.length < pageLimit) break;
    offset += pageLimit;
  }
