function pickDefaultGroupColumns(columns: string[]): string[] {
  const prefer = [
    'session_source',
    'session_medium',
    'country_id',
    'session_campaign_name',
    'campaign_name',
    'date',
  ];
  const picked: string[] = [];
  for (const p of prefer) {
    if (columns.includes(p)) picked.push(p);
  }
  if (picked.length) return picked.slice(0, 3);
  return columns[0] ? [columns[0]] : [];
}

