async listRecordsAggregate(
  tenantId: string,
  objectId: string,
  options: { groupBy: string; sumKeys: string[]; textKeys?: string[] },
) {
  await this.getObject(tenantId, objectId);
  const fields = await this.listFields(tenantId, objectId);
  const allowed = new Set(fields.filter((f) => f.isActive).map((f) => f.key));

  const groupBy = options.groupBy?.trim() || '';
  if (!groupBy || !CustomObjectsService.AGG_FIELD_KEY.test(groupBy) || !allowed.has(groupBy)) {
    throw new BadRequestException('Invalid or unknown groupBy field');
  }

  const sumKeys = options.sumKeys.filter(
    (k) => CustomObjectsService.AGG_FIELD_KEY.test(k) && allowed.has(k),
  );

  const textKeysRaw = options.textKeys || [];
  const textKeys = textKeysRaw.filter(
    (k) =>
      CustomObjectsService.AGG_FIELD_KEY.test(k) &&
      allowed.has(k) &&
      k !== groupBy &&
      !sumKeys.includes(k),
  );

  const esc = (k: string) => k.replace(/'/g, "''");
  const groupExpr = `COALESCE(record.values->>'${esc(groupBy)}', '')`;

  const sumParts = sumKeys.map((k, idx) => {
    const ke = esc(k);
    return `COALESCE(SUM(
      CASE
        WHEN (record.values->>'${ke}') IS NULL OR trim(record.values->>'${ke}') = '' THEN 0::double precision
        WHEN (record.values->>'${ke}') ~ '^-?[0-9]+(\\.[0-9]+)?([eE][+-]?[0-9]+)?$'
          THEN (record.values->>'${ke}')::double precision
        ELSE 0::double precision
      END
    ), 0)::double precision AS "sum_${idx}"`;
  });

  /** Одно представительское текстовое значение в группе (для примечаний, ответственного и т.д.). */
  const textParts = textKeys.map((k, idx) => {
    const ke = esc(k);
    return `MAX(NULLIF(TRIM(BOTH FROM record.values->>'${ke}'), ''))::text AS "text_${idx}"`;
  });

  /** Без sumKeys — только группы и количество строк (сводка по категориям без числовых полей). */
  const orderCol =
    sumKeys.length > 0 ? `"sum_0" DESC NULLS LAST` : `"count" DESC NULLS LAST`;

  const extraSelect = [...sumParts, ...textParts].filter(Boolean);
  const sql = `
    SELECT ${groupExpr} AS "groupKey",
           COUNT(*)::int AS "count"
           ${extraSelect.length ? ',' + extraSelect.join(',') : ''}
    FROM "custom_object_records" record
    WHERE record."tenantId" = $1 AND record."objectId" = $2::uuid
    GROUP BY ${groupExpr}
    ORDER BY ${orderCol}, "groupKey" ASC
    LIMIT 5000
  `;

  const raw: Array<Record<string, unknown>> = await this.recordRepo.query(sql, [
    tenantId,
    objectId,
  ]);

  return {
    groupBy,
    sumKeys,
    textKeys,
    rows: raw.map((row) => {
      const sums: Record<string, number> = {};
      sumKeys.forEach((k, idx) => {
        const v = row[`sum_${idx}`];
        sums[k] = typeof v === 'string' ? parseFloat(v) : Number(v) || 0;
      });
      const texts: Record<string, string> = {};
      textKeys.forEach((k, idx) => {
        const v = row[`text_${idx}`];
        texts[k] = v === null || v === undefined ? '' : String(v);
      });
      return {
        groupKey: String(row.groupKey ?? ''),
        count: Number(row.count) || 0,
        sums,
        texts,
      };
    }),
  };
}

