import type { CustomObjectField } from '../api/customObjects';

/**
 * Рендерить date/datetime input только для настоящих дат.
 * Раньше key.endsWith('id') отсекал «date_paid» (окончание …paid → …id).
 */
export function isRenderableWorkspaceDateField(field: CustomObjectField): boolean {
  const type = String(field.type || '').toLowerCase();
  if (type !== 'date' && type !== 'datetime') return false;
  const kl = String(field.key || '').toLowerCase();
  const ll = String(field.label || '').toLowerCase();
  if (kl === 'id' || kl.endsWith('_id') || kl.includes('id_') || ll.endsWith(' id')) {
    return false;
  }
  return true;
}

import type { CustomObjectField } from '../api/customObjects';

/** meta.workspaceEntityRef — колонка хранит UUID лида или проекта CRM */
export const WORKSPACE_ENTITY_REF_KEY = 'workspaceEntityRef' as const;

export type WorkspaceEntityRefKind = 'lead' | 'project';

export function parseWorkspaceEntityRef(
  meta: Record<string, unknown> | null | undefined,
): WorkspaceEntityRefKind | null {
  if (!meta || typeof meta !== 'object') return null;
  const v = (meta as Record<string, unknown>)[WORKSPACE_ENTITY_REF_KEY];
  if (v === 'lead' || v === 'project') return v;
  return null;
}

export function isWorkspaceEntityRefField(field: CustomObjectField): WorkspaceEntityRefKind | null {
  if (field.type !== 'text') return null;
  return parseWorkspaceEntityRef(field.meta as Record<string, unknown> | null);
}

