export const WorkspaceCrmEntityMultiField: React.FC<WorkspaceCrmEntityMultiFieldProps> = ({
  entity,
  rawValue,
  leads,
  projects,
  onCommit,
  variant = 'table',
  className = '',
}) => {
  const { t } = useTranslation();
  const ids = useMemo(() => parseCrmEntityIdsFromCell(rawValue), [rawValue]);
  const rootRef = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(false);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [q, setQ] = useState('');
  const [debouncedQ, setDebouncedQ] = useState('');
  const [leadSearchHits, setLeadSearchHits] = useState<Lead[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);

  useEffect(() => {
    const tmr = window.setTimeout(() => setDebouncedQ(q.trim()), 220);
    return () => window.clearTimeout(tmr);
  }, [q]);

  useEffect(() => {
    if (entity !== 'lead' || !pickerOpen) {
      setLeadSearchHits([]);
      return;
    }
    if (debouncedQ.length < 1) {
      setLeadSearchHits([]);
      setSearchLoading(false);
      return;
    }
    let cancelled = false;
    setSearchLoading(true);
    searchLeadsQuick(debouncedQ, 30)
      .then((list) => {
        if (!cancelled) {
          setLeadSearchHits(list.filter((l) => !isLeadOmittedFromAnalytics(l)));
        }
      })
      .catch(() => {
        if (!cancelled) setLeadSearchHits([]);
      })
      .finally(() => {
        if (!cancelled) setSearchLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [entity, pickerOpen, debouncedQ]);

  const activeProjects = useMemo(
    () => projects.filter((p) => !p.isDeleted),
    [projects],
  );

  const projectSearchResults = useMemo(() => {
    if (entity !== 'project' || !pickerOpen) return [];
    const term = debouncedQ.toLowerCase();
    if (!term) return activeProjects.slice(0, 25);
    return activeProjects
      .filter((p) => (p.name || '').toLowerCase().includes(term))
      .slice(0, 30);
  }, [entity, pickerOpen, debouncedQ, activeProjects]);

  const labelById = useMemo(() => {
    const m = new Map<string, string>();
    leads.forEach((l) => {
      m.set(
        l.id,
        l.name?.trim() || l.email?.trim() || `${l.id.slice(0, 8)}…`,
      );
    });
    activeProjects.forEach((p) => {
      m.set(p.id, p.name?.trim() || `${p.id.slice(0, 8)}…`);
    });
    leadSearchHits.forEach((l) => {
      m.set(
        l.id,
        l.name?.trim() || l.email?.trim() || `${l.id.slice(0, 8)}…`,
      );
    });
    return m;
  }, [leads, activeProjects, leadSearchHits]);

  const commitIds = useCallback(
    (next: string[]) => {
      onCommit(serializeCrmEntityIds(next));
    },
    [onCommit],
  );

  const removeId = useCallback(
    (id: string) => {
      commitIds(ids.filter((x) => x !== id));
    },
    [ids, commitIds],
  );

  const addId = useCallback(
    (id: string) => {
      if (ids.includes(id)) return;
      commitIds([...ids, id]);
      setQ('');
      setPickerOpen(false);
    },
    [ids, commitIds],
  );

  useEffect(() => {
    if (!focused && !pickerOpen) return;
    const onPointerDown = (e: MouseEvent | PointerEvent) => {
      const el = e.target;
      if (!(el instanceof Node)) return;
      if (rootRef.current?.contains(el)) return;
      setFocused(false);
      setPickerOpen(false);
      setQ('');
    };
    window.addEventListener('mousedown', onPointerDown, true);
    window.addEventListener('pointerdown', onPointerDown, true);
    return () => {
      window.removeEventListener('mousedown', onPointerDown, true);
      window.removeEventListener('pointerdown', onPointerDown, true);
    };
  }, [focused, pickerOpen]);

  const textSm = variant === 'drawer' ? 'text-sm' : 'text-xs';
  const pad = variant === 'drawer' ? 'px-3 py-2' : 'px-2 py-1.5';

  const hrefFor = (id: string) =>
    entity === 'lead' ? `/leads/${id}` : `/projects/${id}`;

  const unknownLabel =
    entity === 'lead'
      ? t('crm.workspace.table.crmLeadUnknown')
      : t('crm.workspace.table.crmProjectUnknown');

  const pickerRows =
    entity === 'lead'
      ? leadSearchHits
      : (projectSearchResults as unknown as Project[]);

  return (
    <div
      ref={rootRef}
      className={`relative min-w-0 ${className}`}
      data-workspace-inline-popover
    >
      <div
        role="button"
        tabIndex={0}
        onClick={() => setFocused(true)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setFocused(true);
          }
        }}
        className={`flex min-h-[32px] w-full flex-wrap items-center gap-1 rounded-lg border bg-white transition-colors ${
          focused ? 'border-lumiva-accent ring-1 ring-lumiva-accent/25' : 'border-slate-200'
        } ${pad}`}
      >
        {focused && (
          <button
            type="button"
            className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md border border-dashed border-slate-300 text-slate-500 hover:bg-slate-50"
            title={t('crm.workspace.table.crmMultiAdd')}
            onClick={(e) => {
              e.stopPropagation();
              setFocused(true);
              setPickerOpen((v) => !v);
            }}
          >
            +
          </button>
        )}
        {ids.length === 0 && !focused && (
          <span className={`text-slate-400 ${textSm}`}>
            {t('crm.workspace.table.crmEntityPlaceholder')}
          </span>
        )}
        {ids.map((id) => {
          const label = labelById.get(id) ?? unknownLabel;
          const Icon = entity === 'lead' ? UsersIcon : FolderIcon;
          return (
            <span
              key={id}
              className="inline-flex max-w-full items-center gap-1 rounded-full bg-sky-50/90 pl-1.5 pr-1 text-slate-800 ring-1 ring-sky-100"
            >
              <Icon />
              <Link
                to={hrefFor(id)}
                target="_blank"
                rel="noreferrer"
                className={`min-w-0 flex-1 truncate font-medium text-lumiva-accent hover:underline ${textSm}`}
                title={t('crm.workspace.table.crmEntityOpen')}
                onClick={(e) => e.stopPropagation()}
              >
                {label}
              </Link>
              {focused && (
                <button
                  type="button"
                  className="inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-slate-500 hover:bg-sky-100 hover:text-slate-800"
                  aria-label={t('crm.workspace.table.crmMultiRemove')}
                  onClick={(e) => {
                    e.stopPropagation();
                    removeId(id);
                  }}
                >
                  ×
                </button>
              )}
            </span>
          );
        })}
      </div>

      {pickerOpen && focused && (
        <div
          className={`absolute left-0 z-[220] mt-1 w-[min(100%,320px)] rounded-xl border border-slate-200 bg-white p-2 shadow-2xl ring-1 ring-slate-100 ${
            variant === 'drawer' ? 'text-sm' : 'text-xs'
          }`}
        >
          <div className="relative mb-2">
            <span className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400">
              <svg className="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="11" cy="11" r="7" />
                <path d="m20 20-3-3" />
              </svg>
            </span>
            <input
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder={
                entity === 'lead'
                  ? t('crm.workspace.table.crmMultiSearchLeadPlaceholder')
                  : t('crm.workspace.table.crmMultiSearchProjectPlaceholder')
              }
